// gen2.mjs START END SIZE -> bash commands using locale-independent \xHH escapes
const start = Number(process.argv[2]);
const end = Number(process.argv[3]);
const size = Number(process.argv[4] || 300);
const skipSurr = process.argv[5] !== 'keepsurr';

function lit(cps) {
  const bytes = [];
  for (const c of cps) {
    // UTF-8 / WTF-8 encode (surrogates encoded as 3-byte sequences)
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return "$'" + bytes.map((b) => '\\x' + b.toString(16).padStart(2, '0')).join('') + "'";
}

const all = [];
for (let c = start; c <= end; c++) {
  if (c === 0) continue;
  if (skipSurr && c >= 0xd800 && c <= 0xdfff) continue;
  all.push(c);
}
for (let i = 0; i < all.length; i += size * 3) {
  const parts = [];
  for (let k = 0; k < 3; k++) {
    const seg = all.slice(i + k * size, i + (k + 1) * size);
    parts.push(seg.length ? lit(seg) : "$'PAD" + k + "'");
  }
  const lo = all[i], hi = all[Math.min(i + size * 3 - 1, all.length - 1)];
  console.log(
    `# U+${lo.toString(16).toUpperCase().padStart(4, '0')}..U+${hi.toString(16).toUpperCase().padStart(4, '0')}\n` +
      '/tmp/dt.sh --a ' + parts[0] + ' --b ' + parts[1] + ' --c ' + parts[2]
  );
}

import { readFileSync } from 'node:fs';
const py = readFileSync('/tmp/w/py.out', 'utf8');
const js = readFileSync('/tmp/w/js.out', 'utf8');
const pl = py.split('\n'), jl = js.split('\n');
console.log('lines py', pl.length, 'js', jl.length);
for (let i = 0; i < Math.max(pl.length, jl.length); i++) {
  if (pl[i] === jl[i]) continue;
  console.log('--- line', i + 1, 'differs ---');
  const a = pl[i] ?? '', b = jl[i] ?? '';
  // tokenise the repr body into escape sequences / literal chars
  const tok = (s) => {
    const t = [];
    let k = 0;
    while (k < s.length) {
      if (s[k] === '\\' && 'xuU'.includes(s[k + 1])) {
        const n = s[k + 1] === 'x' ? 2 : s[k + 1] === 'u' ? 4 : 8;
        t.push(s.slice(k, k + 2 + n)); k += 2 + n;
      } else if (s[k] === '\\') { t.push(s.slice(k, k + 2)); k += 2; }
      else { const c = String.fromCodePoint(s.codePointAt(k)); t.push(c); k += c.length; }
    }
    return t;
  };
  const ta = tok(a), tb = tok(b);
  let shown = 0;
  for (let j = 0, k = 0; j < ta.length || k < tb.length; ) {
    if (ta[j] === tb[k]) { j++; k++; continue; }
    // report and try to resync assuming same code point, different rendering
    const dec = (t) => t && t[0] === '\\' && 'xuU'.includes(t[1]) ? parseInt(t.slice(2), 16) : (t ? t.codePointAt(0) : -1);
    const cpa = dec(ta[j]), cpb = dec(tb[k]);
    console.log(`  py=${JSON.stringify(ta[j])} (U+${cpa.toString(16).toUpperCase()})  js=${JSON.stringify(tb[k])} (U+${cpb.toString(16).toUpperCase()})`);
    shown++;
    if (shown > 40) { console.log('  ...more'); break; }
    if (cpa === cpb) { j++; k++; } else if (cpa < cpb) j++; else k++;
  }
  break;
}

// gen3.mjs START END SIZE MODE  (MODE: fwd|rev|stride)
const start = Number(process.argv[2]);
const end = Number(process.argv[3]);
const size = Number(process.argv[4] || 250);
const mode = process.argv[5] || 'rev';

function lit(cps) {
  const bytes = [];
  for (const c of cps) {
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return "$'" + bytes.map((b) => '\\x' + b.toString(16).padStart(2, '0')).join('') + "'";
}

let all = [];
for (let c = start; c <= end; c++) { if (c === 0) continue; all.push(c); }
if (mode === 'rev') all.reverse();
if (mode === 'stride') {
  const out = [];
  const S = 7;
  for (let o = 0; o < S; o++) for (let i = o; i < all.length; i += S) out.push(all[i]);
  all = out;
}
for (let i = 0; i < all.length; i += size * 3) {
  const parts = [];
  for (let k = 0; k < 3; k++) {
    const seg = all.slice(i + k * size, i + (k + 1) * size);
    parts.push(seg.length ? lit(seg) : "$'PAD" + k + "'");
  }
  console.log('# ' + mode + ' block ' + (i / (size * 3) + 1) + '\n/tmp/dt.sh --a ' + parts[0] + ' --b ' + parts[1] + ' --c ' + parts[2]);
}
